async function metadataLineTops(node){return node.evaluate(el=>{const tops=new Set(),walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);for(let t=walker.nextNode();t;t=walker.nextNode()){if(!t.textContent.trim())continue;const r=document.createRange();r.selectNodeContents(t);for(const box of r.getClientRects())tops.add(Math.round(box.top*2)/2);}return[...tops].sort((a,b)=>a-b);});}
async function closeRoutedActivityContext(context){await context.unrouteAll({behavior:'wait'});await context.close();}
async function activityMetadataWidths(meta){return meta.evaluate(el=>{const width=selector=>el.querySelector(selector).getBoundingClientRect().width,gap=parseFloat(getComputedStyle(el).columnGap)||0,person=width('.post-meta-person'),name=width('.post-name'),date=width('.post-meta-date'),kind=width('.post-meta-kind');return{available:el.getBoundingClientRect().width,required:person+date+kind+2*gap,oldRequired:name+date+kind+gap,person,name,date,kind,gap,gapCount:2};});}
